#!/usr/bin/env python3
"""Replaces 29 old topic pages in sat-math/ with rewritten versions.
Checks every file's fingerprint first. Changes nothing unless all 29 match.
Backups go to .topics_backup_20261027. Undo: python3 topics_oct27.py --undo"""
import sys,os,json,base64,zlib,hashlib,shutil
PAGES=json.loads('{"triangle-similarity": {"old": "5989dca09469af99", "new": "c85882c4668d99fd", "data": ""}, "negative-and-fractional-exponents": {"old": "13ef66561ba7cbf9", "new": "072ba6423706da26", "data": ""}, "translating-word-problems": {"old": "0567a077b30eb37b", "new": "118edabd7754b053", "data": ""}, "percent-increase-and-decrease": {"old": "1f2f00c6fd555e79", "new": "75b4cdbeb717d885", "data": ""}, "scatterplots": {"old": "9e4e74c3e2ac40fb", "new": "364b6f6b833e1924", "data": ""}, "polynomial-factors-and-zeros": {"old": "cbeffbef25cea9b6", "new": "6667ef51b17afead", "data": ""}, "zeros-of-quadratics": {"old": "2730fd98834929a1", "new": "6eeb888e90554e5e", "data": ""}, "completing-the-square": {"old": "6405654c13e1835b", "new": "526cffd2791a546c", "data": ""}, "parabola-vertex-axis-of-symmetry": {"old": "c36f4b285feaa3da", "new": "ec6ba5a37e091b47", "data": ""}, "exponent-rules": {"old": "097908658435984f", "new": "ace43abd239e3dea", "data": ""}, "polynomial-end-behavior": {"old": "3dad1babad23cee5", "new": "9aa406e78e3e0cfc", "data": ""}, "circle-equations": {"old": "fab83133094cc517", "new": "5f7ba4ddf9c5f453", "data": ""}, "slope-rate-of-change": {"old": "569bb379ebe26281", "new": "c1e5791a5c9b6e98", "data": ""}, "standard-to-slope-intercept-form": {"old": "38486f68617c3e39", "new": "a69fa3a7d985f2e9", "data": ""}, "linear-equation-point-slope": {"old": "e8a048cf1a0a2734", "new": "a8ced8930eb24eef", "data": ""}, "linear-equation-from-two-points": {"old": "c580a9f6bdf05c49", "new": "4a81a84db50eb7df", "data": ""}, "y-intercept-in-context": {"old": "41928ef65034935a", "new": "07d5c7e11c4bbd39", "data": ""}, "linear-inequalities": {"old": "8e9d65083335fa9b", "new": "4e1dc44a4b2f720d", "data": ""}, "graphing-systems-of-equations": {"old": "b719662330290bca", "new": "680688062a1f4f91", "data": ""}, "linear-word-problems": {"old": "2b82aee8da688317", "new": "a038117f77b1b967", "data": ""}, "linear-models-from-context": {"old": "af633312dc208726", "new": "cdcafa394687283a", "data": ""}, "line-of-best-fit": {"old": "372fddc72c9a24aa", "new": "33209d7a2d29ad37", "data": ""}, "distance-formula": {"old": "2a6e18ea4dcd9012", "new": "2ae723ecd58aecf5", "data": ""}, "complementary-angle-trig": {"old": "d7e63daebcb4deb1", "new": "9c6e5e8ee33d749f", "data": ""}, "successive-percent-changes": {"old": "a645be976f613ea6", "new": "94fc9c8e65bca6ac", "data": ""}, "reverse-percent-problems": {"old": "d8869495d4e0a809", "new": "6f128319eea8e918", "data": ""}, "basic-probability": {"old": "23c231ed5c97eca5", "new": "c5447cc678faca4c", "data": ""}, "compound-probability": {"old": "d23c90cc6f8b65f2", "new": "11b13a8c93190ba6", "data": ""}, "comparing-distributions": {"old": "5b17b08bf9eec450", "new": "bfd81300dec6f77c", "data": ""}}')
BK='.topics_backup_20261027'
fp=lambda b: hashlib.sha256(b).hexdigest()[:16]
path=lambda s: os.path.join('sat-math',s,'index.html')
if '--undo' in sys.argv:
    if not os.path.isdir(BK): sys.exit('No backup found. Nothing undone.')
    for s in PAGES:
        b=os.path.join(BK,s+'.html')
        if os.path.exists(b): shutil.copyfile(b,path(s))
    print('UNDONE: 29 pages restored. Click Republish.'); sys.exit()
bad=[]; todo=[]
for s,p in PAGES.items():
    if not os.path.exists(path(s)): bad.append(s+' (missing)'); continue
    h=fp(open(path(s),'rb').read())
    if h==p['new']: continue
    if h!=p['old']: bad.append(s+' (changed since checked)'); continue
    todo.append(s)
if bad:
    print('STOP. Nothing was changed. These files differ from what was checked:'); print('\n'.join(bad)); sys.exit(1)
if not todo: print('Already done. Nothing to change.'); sys.exit()
os.makedirs(BK,exist_ok=True)
for s in todo: shutil.copyfile(path(s),os.path.join(BK,s+'.html'))
for s in todo:
    b=zlib.decompress(base64.b64decode(PAGES[s]['data']))
    assert fp(b)==PAGES[s]['new']
    open(path(s),'wb').write(b)
print('DONE: %d topic pages replaced. Click Republish.'%len(todo))
